dfp_read_field_def_create_request(<<10, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, F@_3, TrUserData) -> d_field_create_request_identity(Rest, Z1, Z2, F, F@_1, F@_2, F@_3, TrUserData);
