d_field_create_request_identity(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, F@_3, TrUserData) when N < 57 -> d_field_create_request_identity(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, F@_3, TrUserData);
d_field_create_request_identity(<<0:1, X:7, Rest/binary>>, N, Acc, F, Prev, F@_2, F@_3, TrUserData) ->
    {NewFValue, RestF} = begin Len = X bsl N + Acc, <<Bs:Len/binary, Rest2/binary>> = Rest, {id(decode_msg_identity(Bs, TrUserData), TrUserData), Rest2} end,
    dfp_read_field_def_create_request(RestF,
                                      0,
                                      0,
                                      F,
                                      if Prev == '$undef' -> NewFValue;
                                         true -> merge_msg_identity(Prev, NewFValue, TrUserData)
                                      end,
                                      F@_2,
                                      F@_3,
                                      TrUserData).

