decode_msg_turn_response(Bin, TrUserData) -> dfp_read_field_def_turn_response(Bin, 0, 0, 0, id([], TrUserData), id(0, TrUserData), TrUserData).

dfp_read_field_def_turn_response(<<10, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> d_field_turn_response_ice_servers(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData);
dfp_read_field_def_turn_response(<<16, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> d_field_turn_response_ttl(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData);
dfp_read_field_def_turn_response(<<>>, 0, 0, _, R1, F@_2, TrUserData) ->
    S1 = #{ttl => F@_2},
    if R1 == '$undef' -> S1;
       true -> S1#{ice_servers => lists_reverse(R1, TrUserData)}
    end;
dfp_read_field_def_turn_response(Other, Z1, Z2, F, F@_1, F@_2, TrUserData) -> dg_read_field_def_turn_response(Other, Z1, Z2, F, F@_1, F@_2, TrUserData).

dg_read_field_def_turn_response(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) when N < 32 - 7 -> dg_read_field_def_turn_response(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData);
dg_read_field_def_turn_response(<<0:1, X:7, Rest/binary>>, N, Acc, _, F@_1, F@_2, TrUserData) ->
    Key = X bsl N + Acc,
    case Key of
        10 -> d_field_turn_response_ice_servers(Rest, 0, 0, 0, F@_1, F@_2, TrUserData);
        16 -> d_field_turn_response_ttl(Rest, 0, 0, 0, F@_1, F@_2, TrUserData);
        _ ->
            case Key band 7 of
                0 -> skip_varint_turn_response(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                1 -> skip_64_turn_response(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                2 -> skip_length_delimited_turn_response(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                3 -> skip_group_turn_response(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData);
                5 -> skip_32_turn_response(Rest, 0, 0, Key bsr 3, F@_1, F@_2, TrUserData)
            end
    end;
dg_read_field_def_turn_response(<<>>, 0, 0, _, R1, F@_2, TrUserData) ->
    S1 = #{ttl => F@_2},
    if R1 == '$undef' -> S1;
       true -> S1#{ice_servers => lists_reverse(R1, TrUserData)}
    end.

d_field_turn_response_ice_servers(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) when N < 57 -> d_field_turn_response_ice_servers(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData);
d_field_turn_response_ice_servers(<<0:1, X:7, Rest/binary>>, N, Acc, F, Prev, F@_2, TrUserData) ->
    {NewFValue, RestF} = begin Len = X bsl N + Acc, <<Bs:Len/binary, Rest2/binary>> = Rest, {id(decode_msg_ice_server(Bs, TrUserData), TrUserData), Rest2} end,
    dfp_read_field_def_turn_response(RestF, 0, 0, F, cons(NewFValue, Prev, TrUserData), F@_2, TrUserData).

d_field_turn_response_ttl(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) when N < 57 -> d_field_turn_response_ttl(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData);
d_field_turn_response_ttl(<<0:1, X:7, Rest/binary>>, N, Acc, F, F@_1, _, TrUserData) ->
    {NewFValue, RestF} = {begin <<Res:64/signed-native>> = <<(X bsl N + Acc):64/unsigned-native>>, id(Res, TrUserData) end, Rest},
    dfp_read_field_def_turn_response(RestF, 0, 0, F, F@_1, NewFValue, TrUserData).

skip_varint_turn_response(<<1:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> skip_varint_turn_response(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData);
skip_varint_turn_response(<<0:1, _:7, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> dfp_read_field_def_turn_response(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData).

skip_length_delimited_turn_response(<<1:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) when N < 57 -> skip_length_delimited_turn_response(Rest, N + 7, X bsl N + Acc, F, F@_1, F@_2, TrUserData);
skip_length_delimited_turn_response(<<0:1, X:7, Rest/binary>>, N, Acc, F, F@_1, F@_2, TrUserData) ->
    Length = X bsl N + Acc,
    <<_:Length/binary, Rest2/binary>> = Rest,
    dfp_read_field_def_turn_response(Rest2, 0, 0, F, F@_1, F@_2, TrUserData).

skip_group_turn_response(Bin, _, Z2, FNum, F@_1, F@_2, TrUserData) ->
    {_, Rest} = read_group(Bin, FNum),
    dfp_read_field_def_turn_response(Rest, 0, Z2, FNum, F@_1, F@_2, TrUserData).

skip_32_turn_response(<<_:32, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> dfp_read_field_def_turn_response(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData).

skip_64_turn_response(<<_:64, Rest/binary>>, Z1, Z2, F, F@_1, F@_2, TrUserData) -> dfp_read_field_def_turn_response(Rest, Z1, Z2, F, F@_1, F@_2, TrUserData).

read_group(Bin, FieldNum) ->
    {NumBytes, EndTagLen} = read_gr_b(Bin, 0, 0, 0, 0, FieldNum),
    <<Group:NumBytes/binary, _:EndTagLen/binary, Rest/binary>> = Bin,
    {Group, Rest}.

%% Like skipping over fields, but record the total length,
%% Each field is <(FieldNum bsl 3) bor FieldType> ++ <FieldValue>
%% Record the length because varints may be non-optimally encoded.
%%
%% Groups can be nested, but assume the same FieldNum cannot be nested
%% because group field numbers are shared with the rest of the fields
%% numbers. Thus we can search just for an group-end with the same
%% field number.
%%
%% (The only time the same group field number could occur would
%% be in a nested sub message, but then it would be inside a
%% length-delimited entry, which we skip-read by length.)
read_gr_b(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen, FieldNum)
  when N < (32-7) ->
    read_gr_b(Tl, N+7, X bsl N + Acc, NumBytes, TagLen+1, FieldNum);
read_gr_b(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, TagLen,
          FieldNum) ->
    Key = X bsl N + Acc,
    TagLen1 = TagLen + 1,
    case {Key bsr 3, Key band 7} of
        {FieldNum, 4} -> % 4 = group_end
            {NumBytes, TagLen1};
        {_, 0} -> % 0 = varint
            read_gr_vi(Tl, 0, NumBytes + TagLen1, FieldNum);
        {_, 1} -> % 1 = bits64
            <<_:64, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 8, 0, FieldNum);
        {_, 2} -> % 2 = length_delimited
            read_gr_ld(Tl, 0, 0, NumBytes + TagLen1, FieldNum);
        {_, 3} -> % 3 = group_start
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 4} -> % 4 = group_end
            read_gr_b(Tl, 0, 0, NumBytes + TagLen1, 0, FieldNum);
        {_, 5} -> % 5 = bits32
            <<_:32, Tl2/binary>> = Tl,
            read_gr_b(Tl2, 0, 0, NumBytes + TagLen1 + 4, 0, FieldNum)
    end.

read_gr_vi(<<1:1, _:7, Tl/binary>>, N, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_vi(Tl, N+7, NumBytes+1, FieldNum);
read_gr_vi(<<0:1, _:7, Tl/binary>>, _, NumBytes, FieldNum) ->
    read_gr_b(Tl, 0, 0, NumBytes+1, 0, FieldNum).

read_gr_ld(<<1:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum)
  when N < (64-7) ->
    read_gr_ld(Tl, N+7, X bsl N + Acc, NumBytes+1, FieldNum);
read_gr_ld(<<0:1, X:7, Tl/binary>>, N, Acc, NumBytes, FieldNum) ->
    Len = X bsl N + Acc,
    NumBytes1 = NumBytes + 1,
    <<_:Len/binary, Tl2/binary>> = Tl,
    read_gr_b(Tl2, 0, 0, NumBytes1 + Len, 0, FieldNum).

merge_msgs(Prev, New, MsgName) when is_atom(MsgName) -> merge_msgs(Prev, New, MsgName, []).

merge_msgs(Prev, New, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        identity -> merge_msg_identity(Prev, New, TrUserData);
        create_request -> merge_msg_create_request(Prev, New, TrUserData);
        accept_request -> merge_msg_accept_request(Prev, New, TrUserData);
        reject_request -> merge_msg_reject_request(Prev, New, TrUserData);
        cancel_request -> merge_msg_cancel_request(Prev, New, TrUserData);
        connected_request -> merge_msg_connected_request(Prev, New, TrUserData);
        hangup_request -> merge_msg_hangup_request(Prev, New, TrUserData);
        heartbeat_request -> merge_msg_heartbeat_request(Prev, New, TrUserData);
        signal_request -> merge_msg_signal_request(Prev, New, TrUserData);
        get_request -> merge_msg_get_request(Prev, New, TrUserData);
        list_active_request -> merge_msg_list_active_request(Prev, New, TrUserData);
        signals_request -> merge_msg_signals_request(Prev, New, TrUserData);
        turn_request -> merge_msg_turn_request(Prev, New, TrUserData);
        call -> merge_msg_call(Prev, New, TrUserData);
        create_response -> merge_msg_create_response(Prev, New, TrUserData);
        accept_response -> merge_msg_accept_response(Prev, New, TrUserData);
        reject_response -> merge_msg_reject_response(Prev, New, TrUserData);
        cancel_response -> merge_msg_cancel_response(Prev, New, TrUserData);
        connected_response -> merge_msg_connected_response(Prev, New, TrUserData);
        hangup_response -> merge_msg_hangup_response(Prev, New, TrUserData);
        heartbeat_response -> merge_msg_heartbeat_response(Prev, New, TrUserData);
        get_response -> merge_msg_get_response(Prev, New, TrUserData);
        signal_response -> merge_msg_signal_response(Prev, New, TrUserData);
        list_active_response -> merge_msg_list_active_response(Prev, New, TrUserData);
        signal -> merge_msg_signal(Prev, New, TrUserData);
        signals_response -> merge_msg_signals_response(Prev, New, TrUserData);
        ice_server -> merge_msg_ice_server(Prev, New, TrUserData);
        turn_response -> merge_msg_turn_response(Prev, New, TrUserData)
    end.

-compile({nowarn_unused_function,merge_msg_identity/3}).
merge_msg_identity(PMsg, NMsg, _) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {_, #{access_token := NFaccess_token}} -> S1#{access_token => NFaccess_token};
             {#{access_token := PFaccess_token}, _} -> S1#{access_token => PFaccess_token};
             _ -> S1
         end,
    S3 = case {PMsg, NMsg} of
             {_, #{user_id := NFuser_id}} -> S2#{user_id => NFuser_id};
             {#{user_id := PFuser_id}, _} -> S2#{user_id => PFuser_id};
             _ -> S2
         end,
    case {PMsg, NMsg} of
        {_, #{session_id := NFsession_id}} -> S3#{session_id => NFsession_id};
        {#{session_id := PFsession_id}, _} -> S3#{session_id => PFsession_id};
        _ -> S3
    end.

-compile({nowarn_unused_function,merge_msg_create_request/3}).
merge_msg_create_request(PMsg, NMsg, TrUserData) ->
    S1 = #{},
    S2 = case {PMsg, NMsg} of
             {#{identity := PFidentity}, #{identity := NFidentity}} -> S1#{identity => merge_msg_identity(PFidentity, NFidentity, TrUserData)};
             {_, #{identity := NFidentity}} -> S1#{identity => NFidentity};
             {#{identity := PFidentity}, _} -> S1#{identity => PFidentity};
             {_, _} -> S1
         end,
    S3 = case {PMsg, NMsg} of
             {_, #{room_id := NFroom_id}} -> S2#{room_id => NFroom_id};
             {#{room_id := PFroom_id}, _} -> S2#{room_id => PFroom_id};
             _ -> S2
         end,
    case {PMsg, NMsg} of
        {_, #{command_id := NFcommand_id}} -> S3#{command_id => NFcommand_id};
        {#{command_id := PFcommand_id}, _} -> S3#{command_id => PFcommand_id};
