verify_msg(Msg, MsgName) when is_atom(MsgName) -> verify_msg(Msg, MsgName, []).

verify_msg(Msg, MsgName, Opts) ->
    TrUserData = proplists:get_value(user_data, Opts),
    case MsgName of
        identity -> v_msg_identity(Msg, [MsgName], TrUserData);
        create_request -> v_msg_create_request(Msg, [MsgName], TrUserData);
        accept_request -> v_msg_accept_request(Msg, [MsgName], TrUserData);
        reject_request -> v_msg_reject_request(Msg, [MsgName], TrUserData);
        cancel_request -> v_msg_cancel_request(Msg, [MsgName], TrUserData);
        connected_request -> v_msg_connected_request(Msg, [MsgName], TrUserData);
        hangup_request -> v_msg_hangup_request(Msg, [MsgName], TrUserData);
        heartbeat_request -> v_msg_heartbeat_request(Msg, [MsgName], TrUserData);
        signal_request -> v_msg_signal_request(Msg, [MsgName], TrUserData);
        get_request -> v_msg_get_request(Msg, [MsgName], TrUserData);
        list_active_request -> v_msg_list_active_request(Msg, [MsgName], TrUserData);
        signals_request -> v_msg_signals_request(Msg, [MsgName], TrUserData);
        turn_request -> v_msg_turn_request(Msg, [MsgName], TrUserData);
        call -> v_msg_call(Msg, [MsgName], TrUserData);
        create_response -> v_msg_create_response(Msg, [MsgName], TrUserData);
        accept_response -> v_msg_accept_response(Msg, [MsgName], TrUserData);
        reject_response -> v_msg_reject_response(Msg, [MsgName], TrUserData);
        cancel_response -> v_msg_cancel_response(Msg, [MsgName], TrUserData);
        connected_response -> v_msg_connected_response(Msg, [MsgName], TrUserData);
        hangup_response -> v_msg_hangup_response(Msg, [MsgName], TrUserData);
        heartbeat_response -> v_msg_heartbeat_response(Msg, [MsgName], TrUserData);
        get_response -> v_msg_get_response(Msg, [MsgName], TrUserData);
        signal_response -> v_msg_signal_response(Msg, [MsgName], TrUserData);
        list_active_response -> v_msg_list_active_response(Msg, [MsgName], TrUserData);
        signal -> v_msg_signal(Msg, [MsgName], TrUserData);
        signals_response -> v_msg_signals_response(Msg, [MsgName], TrUserData);
        ice_server -> v_msg_ice_server(Msg, [MsgName], TrUserData);
        turn_response -> v_msg_turn_response(Msg, [MsgName], TrUserData);
        _ -> mk_type_error(not_a_known_message, Msg, [])
    end.


-compile({nowarn_unused_function,v_submsg_identity/3}).
-dialyzer({nowarn_function,v_submsg_identity/3}).
v_submsg_identity(Msg, Path, TrUserData) -> v_msg_identity(Msg, Path, TrUserData).

-compile({nowarn_unused_function,v_msg_identity/3}).
-dialyzer({nowarn_function,v_msg_identity/3}).
v_msg_identity(#{} = M, Path, TrUserData) ->
    case M of
        #{access_token := F1} -> v_type_string(F1, [access_token | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{user_id := F2} -> v_type_string(F2, [user_id | Path], TrUserData);
        _ -> ok
    end,
    case M of
        #{session_id := F3} -> v_type_string(F3, [session_id | Path], TrUserData);
        _ -> ok
    end,
    lists:foreach(fun (access_token) -> ok;
                      (user_id) -> ok;
                      (session_id) -> ok;
                      (OtherKey) -> mk_type_error({extraneous_key, OtherKey}, M, Path)
                  end,
                  maps:keys(M)),
    ok;
v_msg_identity(M, Path, _TrUserData) when is_map(M) -> mk_type_error({missing_fields, [] -- maps:keys(M), identity}, M, Path);
v_msg_identity(X, Path, _TrUserData) -> mk_type_error({expected_msg, identity}, X, Path).

